class ZipManager:
    \"\"\"Append uncompressed files once, reopening existing batches on retries.\"\"\"

    def __init__(self):
        self.zipfiles = {}
        self.names = {}

    def get_zipfile(self, name):
        match = re.fullmatch(r'(\\d{10})(?:-([SML]))?\\.([a-zA-Z0-9]+)', name)
        if not match:
            raise ValueError(f'Invalid cover archive filename: {name}')
        cover_id, suffix, _ext = match.groups()
        size = suffix.lower() if suffix else ''
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            zf = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)
            self.zipfiles[path] = zf
            self.names[path] = set(zf.namelist())
        return path, self.zipfiles[path]

    def add_file(self, name, filepath, mtime):
        path, zf = self.get_zipfile(name)
        if name not in self.names[path]:
            info = zipfile.ZipInfo(name, datetime.datetime.fromtimestamp(max(mtime, 315532800)).timetuple()[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source, zf.open(info, 'w') as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            self.names[path].add(name)
        return os.path.relpath(path, config.data_root) + '/' + name

    def close(self):
        for zf in self.zipfiles.values():
            zf.close()
        self.zipfiles.clear()
        self.names.clear()


