class Uploader:
    def upload(self, itemname, filepaths):
        if not filepaths:
            return None
        return subprocess.run(['ia', 'upload', itemname, *filepaths, '--retries', '10'],
                              text=True, capture_output=True, check=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = subprocess.run(['ia', 'list', item], text=True, capture_output=True, check=True)
        found = zip_filename in result.stdout.splitlines()
        if verbose:
            print(item, zip_filename, 'uploaded' if found else 'missing')
        return found


@contextmanager
def _batch_lock(item_id, batch_id):
    directory = os.path.join(config.data_root, 'items', '.locks')
    os.makedirs(directory, exist_ok=True)
    path = os.path.join(directory, f'covers_{item_id}_{batch_id}.lock')
    with open(path, 'a+b') as lock:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as exc:
            raise RuntimeError(f'Batch {item_id}_{batch_id} is already being processed') from exc
        try:
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


class Batch:
    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = self._norm_ids(item_id, batch_id)
        self.size = None if size is None else _size(size)

    @staticmethod
    def _norm_ids(item_id, batch_id):
        item_id, batch_id = int(item_id), int(batch_id)
        if not 0 <= item_id < 10_000 or not 0 <= batch_id < 100:
            raise ValueError('Invalid item or batch ID')
        return f'{item_id:04d}', f'{batch_id:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls._norm_ids(item_id, batch_id)
        _size(size)
        if ext "'!= '"'zip':
            raise ValueError('Batch archive extension must be zip')
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        return f'items/{item}/{item}_{batch_id}.{ext}'

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    def _item(self, size):
        return f'{size + \"_\" if size else \"\"}covers_{self.item_id}'

    def _ready(self, uploader):
        # A cover row is finalized only when every rendition is present remotely.
        for size in SIZES:
            path = self.get_abspath(self.item_id, self.batch_id, size)
            if not os.path.isfile(path):
                return False
            if not uploader.is_uploaded(self._item(size), os.path.basename(path)):
                return False
        rows = CoverDB().get_batch(int(self.item_id) * 1_000_000 + int(self.batch_id) * BATCH_SIZE)
        for size in SIZES:
            path = self.get_abspath(self.item_id, self.batch_id, size)
            with zipfile.ZipFile(path) as zf:
                names = set(zf.namelist())
            suffix = f'-{size.upper()}' if size else ''
            if any(f'{int(row.id):010d}{suffix}.jpg' not in names for row in rows):
                return False
        return True

    def finalize(self, start_id=None, test=False, uploader=None):
        uploader = uploader or Uploader()
        if not self._ready(uploader):
            return False
        if test:
            return True
        start = int(self.item_id) * 1_000_000 + int(self.batch_id) * BATCH_SIZE
        rows = list(CoverDB().get_batch(start))
        old_paths = [path for row in rows for _, path in Cover(row).local_files()]
        transaction = db.getdb().transaction()
        try:
            CoverDB.update_completed_batch(self.item_id, self.batch_id)
        except Exception:
            transaction.rollback()
            raise
        else:
            transaction.commit()
        for path in old_paths:
            if os.path.exists(path):
                os.remove(path)
        for size in SIZES:
            os.remove(self.get_abspath(self.item_id, self.batch_id, size))
        return True

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        uploader = uploader or Uploader()
        with _batch_lock(self.item_id, self.batch_id):
            sizes = SIZES if self.size is None else (self.size,)
            for size in sizes:
                path = self.get_abspath(self.item_id, self.batch_id, size)
                if not os.path.isfile(path):
                    continue
                item = self._item(size)
                if upload and not uploader.is_uploaded(item, os.path.basename(path)) and not test:
                    uploader.upload(item, [path])
                if upload and not uploader.is_uploaded(item, os.path.basename(path)):
                    return False
            if finalize:
                return self.finalize(test=test, uploader=uploader)
            return True


def archive(test=True):
    \"\"\"Stage the next eligible 10k ID range; keep source files until upload is verified.\"\"\"
    database = db.getdb()
    rows = list(database.select('cover', where='archived="'$false AND failed=$false AND uploaded=$false AND id>=8000000'"',
                                order='id', vars={'false': False}, limit=BATCH_SIZE))
    if not rows:
        return None
    item_id, batch_id = Cover.id_to_item_and_batch_id(rows[0].id)
    with _batch_lock(item_id, batch_id):
        manager = ZipManager()
        try:
            for row in rows:
                if Cover.id_to_item_and_batch_id(row.id) "'!= (item_id, batch_id):
                    break
                files = list(Cover(row).local_files())
                if len(files) != len(SIZES) or any(not os.path.isfile(path) for _, path in files):
                    if not test:
                        database.update('"'cover', where='id="'$id'"', vars={'id': row.id}, failed=True)
                    continue
                created = row.created
                if isinstance(created, str):
                    from infogami.infobase.utils import parse_datetime
                    created = parse_datetime(created)
                mtime = time.mktime(created.timetuple())
                for size, path in files:
                    suffix = f'-{size.upper()}' if size else ''
                    manager.add_file(f'{int(row.id):010d}{suffix}.jpg', path, mtime)
        finally:
            manager.close()
    return Batch(item_id, batch_id)
